import { readFileSync } from "node:fs";

import { expect, expectStatus, sample, test } from "../../fixtures";

test("Documents cannot be added to a vendor under review", { tag: "@DOC-06" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const { vendor, documents } = await factory.vendorInReview({ as: "member" });
  const documentsBefore = await expectStatus<unknown[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
    },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");
  const documentsAfter = await expectStatus<{ id: string }[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
  expect(documentsAfter).toHaveLength(documentsBefore.length);
  expect(documentsAfter.map((d) => d.id)).not.toContain(undefined);
  expect(documentsAfter.map((d) => d.id)).toContain(documents.w9.id);
});
